using System.Diagnostics;
using System.Text.Json;
using OpenTK.Input;
using SNESEmulator.Core;
using SNESEmulator.Frontend;
namespace SNESEmulator;
/// <summary>Actual native window with synthetic raw snapshots through its normal polling/routing code.</summary>
internal static class InteractionSmoke
{
    public static void Run(string output)
    {
        Directory.CreateDirectory(output);Directory.CreateDirectory(UserDataPaths.GetSaveDirectory());var steps=new Queue<(string Name,Func<bool> Run)>();var rows=new List<object>();var timer=Stopwatch.StartNew();double next=0;int completed=0;long stateEpoch=0;
        using var w=new SnesWindow();
        void Check(bool ok,string why){if(!ok)throw new InvalidOperationException("M9g native: "+why);}
        void Do(string name,Action action)=>steps.Enqueue((name,()=>{action();return true;}));
        void Wait(string name,Func<bool> ready)=>steps.Enqueue((name,ready));
        void Raw(string name,string[]? keyboard=null,string[]? pad=null,bool focus=true,string? device="synthetic-pad")=>Do(name,()=>w.ProbeInput(focus,device,(pad??[]).ToHashSet(),(keyboard??[]).ToHashSet()));
        void Menu(string name,int row=0)=>Do("open-"+name,()=>w.ProbeOpen(name,row));
        void Apply(string name,Action<EmulatorSettings> edit)=>Do(name,()=>{edit(w.ProbeSettings);w.ProbeApplySettings();});
        Raw("initial-neutral");Do("load-own-diagnostic",()=>w.ProbeKey(Key.F6));Wait("first-live-field",()=>w.RuntimeStatus.Field>=3&&!w.MediaOperationPending);
        Raw("default-F10",["F10"]);Do("default-main-and-no-repeat",()=>Check(w.CurrentMenu=="Main","F10 opens once"));Raw("release-F10");Raw("default-F10-close",["F10"]);Do("main-back-to-game",()=>Check(w.CurrentMenu=="None","F10 closes"));Raw("release-main");
        Raw("default-F11",["F11"]);Do("fullscreen-applied",()=>Check(w.ProbeSettings.Fullscreen,"F11 fullscreen"));Raw("release-fullscreen");Raw("default-F11-return",["F11"]);Do("fullscreen-returned",()=>Check(!w.ProbeSettings.Fullscreen,"fullscreen returns"));Raw("release-fullscreen2");
        Raw("default-F12",["F12"]);Do("saves-path",()=>Check(w.CurrentMenu=="Saves","F12 saves"));Raw("release-saves");
        Apply("remap-back-to-S",s=>s.KeyboardControls!["MenuBack"]="S");Raw("new-mapping-neutral");Raw("back-S-no-legacy-save",["S"]);Do("back-before-state-shortcut",()=>{Check(w.CurrentMenu=="Main","configured Back precedes S save");Check(!Directory.GetFiles(UserDataPaths.GetSaveDirectory(),"*.snessav",SearchOption.AllDirectories).Any(),"S did not save");});Raw("release-S");
        Apply("restore-back-and-main",s=>s.KeyboardControls!["MenuBack"]="Escape");Raw("neutral-restored");Menu("Saves");Do("prepare-one-real-state",()=>w.ProbeKey(Key.S));Wait("state-written",()=>!w.MediaOperationPending&&w.SaveEntries==1);
        Apply("select-Delete",s=>s.KeyboardControls!["MenuSelect"]="Delete");Raw("select-map-neutral");Menu("Saves");Do("remember-load-epoch",()=>stateEpoch=w.RuntimeStatus.Epoch);Raw("Delete-select",["Delete"]);Wait("configured-delete-loaded-state",()=>!w.MediaOperationPending&&w.CurrentMenu=="None");Do("delete-never-opened-confirmation",()=>Check(w.RuntimeStatus.Epoch>stateEpoch,"MenuSelect Delete loads, no Delete->Enter confirmation collision"));Raw("release-delete");
        Apply("network-remap-main-and-up",s=>{s.KeyboardControls!["MenuSelect"]="Enter";s.KeyboardControls["MainMenu"]="K";s.KeyboardControls["Up"]="H";});Raw("network-mapping-neutral");Menu("Network",8);Do("remember-network-host",()=>Check(w.ProbeSettings.Host=="localhost","fixture host"));Raw("K-main-in-network",["K"]);Do("hotkey-before-network-text",()=>Check(w.CurrentMenu=="None"&&w.ProbeSettings.Host=="localhost","K no text before main action"));Raw("release-K");Menu("Network",8);Raw("H-navigation-in-text-row",["H"]);Do("navigation-before-network-text",()=>Check(w.ProbeSelection==7&&w.ProbeSettings.Host=="localhost","H navigates once without text"));Raw("release-H");
        Apply("restore-default-keyboard",s=>s.KeyboardControls=InputBindings.KeyboardDefaults());Raw("defaults-neutral");
        void Capture(string menu,int index,string[] tokens,bool keyboard,string expected)
        {
            Menu(menu,index);Raw("capture-release-"+expected);Do("start-capture-"+expected,()=>w.ProbeActivate());Raw("arm-capture-"+expected);Raw("capture-held-"+expected,keyboard?tokens:null,keyboard?null:tokens);Do("capture-not-committed-until-release-"+expected,()=>Check(w.ProbeCapturing,"hold capture"));Raw("capture-complete-release-"+expected);Do("captured-"+expected,()=>{Check(!w.ProbeCapturing,"capture finished");var name=InputBindings.Buttons.Concat(InputBindings.Actions).ElementAt(index);var map=keyboard?w.ProbeSettings.KeyboardControls!:index<12?w.ProbeSettings.GamepadControls!:w.ProbeSettings.GamepadActions!;Check(map[name]==expected,"captured expression "+map[name]);});
        }
        Capture("Controller",0,["Button9"],false,"Button9");Capture("Controller",1,["Axis3+","Button12"],false,"Axis3+&Button12");Capture("Controller",2,["Hat2Down"],false,"Hat2Down");Capture("Keyboard",0,["ControlLeft","G"],true,"ControlLeft&G");
        Menu("Controller",3);Raw("before-focus-capture");Do("start-focus-capture",()=>w.ProbeActivate());Raw("arm-focus-capture");Raw("pending-focus-capture",pad:["Button18"]);Raw("capture-focus-loss",pad:["Button18"],focus:false);Do("capture-focus-cancelled",()=>Check(!w.ProbeCapturing&&w.ProbeSettings.GamepadControls!["X"]=="Button3","focus cancels without save"));Raw("focus-restored-held",pad:["Button18"]);Raw("focus-restored-release");
        Menu("None");Raw("pad-game-button",pad:["Button9"]);Do("pad-gameplay",()=>Check(w.ProbePadButtons==(ushort)SnesButtons.B,"mapped B"));Raw("background-pad-held",pad:["Button9"],focus:false);Do("background-neutral",()=>Check(w.ProbePadButtons==0,"background game neutral"));Raw("focus-regain-held",pad:["Button9"]);Do("focus-regain-waits-release",()=>Check(w.ProbePadButtons==0,"held after focus ignored"));Raw("focus-neutral");Raw("focus-new-press",pad:["Button9"]);Do("focus-new-press-accepted",()=>Check(w.ProbePadButtons==(ushort)SnesButtons.B,"new focused press"));Raw("hotplug-held",pad:["Button9"],device:"different-pad");Do("hotplug-requires-release",()=>Check(w.ProbePadButtons==0,"hotplug neutral"));Raw("hotplug-neutral",device:"different-pad");
        Menu("None");Raw("default-device-neutral");Raw("overlapping-default-chords",pad:["Button4","Button5","Button6","Button7"]);Do("legacy-save-chord-priority",()=>Check(w.CurrentMenu=="Saves","save chord wins simultaneous main chord"));Raw("overlapping-chords-release");Menu("None");
        Raw("callback-neutral");Menu("None");Do("queue-F10-short-tap",()=>{w.OnUserKeyDown(new SharpPixels.KeyEventArgs(Key.F10,0));w.OnUserKeyUp(new SharpPixels.KeyEventArgs(Key.F10,0));});Do("callback-short-tap-opens-once",()=>Check(w.CurrentMenu=="Main","F10 tap between updates retained"));Menu("Network",8);Do("queue-ordered-repeated-text",()=>{foreach(var key in new[]{Key.N,Key.B,Key.N}){w.OnUserKeyDown(new SharpPixels.KeyEventArgs(key,0));w.OnUserKeyUp(new SharpPixels.KeyEventArgs(key,0));}});Do("callback-text-order",()=>Check(w.ProbeSettings.Host=="localhostnbn","ordered repeated callback characters"));Do("queue-modifier-text",()=>{w.OnUserKeyDown(new SharpPixels.KeyEventArgs(Key.C,KeyModifiers.Shift));w.OnUserKeyUp(new SharpPixels.KeyEventArgs(Key.C,0));w.OnUserKeyDown(new SharpPixels.KeyEventArgs(Key.D,0));w.OnUserKeyDown(new SharpPixels.KeyEventArgs(Key.D,0));w.OnUserKeyUp(new SharpPixels.KeyEventArgs(Key.D,0));});Do("callback-modifiers-and-repeat",()=>Check(w.ProbeSettings.Host=="localhostnbnCdd","per-event shift and held text repeat"));Do("queued-tap-then-focus-cycle",()=>{w.OnUserKeyDown(new SharpPixels.KeyEventArgs(Key.F10,0));w.OnUserKeyUp(new SharpPixels.KeyEventArgs(Key.F10,0));w.ProbeFocusCallback(false);w.ProbeFocusCallback(true);});Do("focus-callback-discards-old-lease",()=>Check(w.CurrentMenu=="Network","focus cycle discarded old hotkey queue"));Do("queue-overflow",()=>{for(int i=0;i<257;i++)w.OnUserKeyDown(new SharpPixels.KeyEventArgs(Key.C,0));});Do("overflow-neutral-visible",()=>Check(w.VisibleStatus.Contains("OVERFLOW")&&w.ProbeSettings.Host=="localhostnbnCdd","bounded callback overflow neutralized"));Menu("None");
        Apply("presentation120",s=>{s.RenderFrameLimit=120;s.PresentationVSync=true;s.VideoZoom=true;});Raw("presentation-neutral");Do("presentation-live",()=>{Check(w.UpdateFrequency==120&&w.PresentationVSyncEnabled,"render cap and vsync applied");RuntimeSmoke.Screenshot(w,Path.Combine(output,"zoom-vsync.png"));});Apply("presentation-unlimited",s=>{s.RenderFrameLimit=0;s.PresentationVSync=false;});Do("presentation-unlimited-live",()=>Check(w.UpdateFrequency==0&&!w.PresentationVSyncEnabled,"unlimited independent host cap"));Apply("presentation60-and-turbo-hotkey",s=>{s.RenderFrameLimit=60;s.KeyboardControls!["Turbo"]="ControlLeft&F7";});Raw("turbo-neutral");Raw("direction-held",["Right"]);Raw("turbo-with-direction",["Right","ControlLeft","F7"]);Do("turbo-edge-keeps-direction",()=>Check(w.ProbeSettings.TurboMode&&w.ProbeKeyboardButtons==(ushort)SnesButtons.Right,"turbo preserves direction"));Do("turbo-held-no-repeat",()=>Check(w.ProbeSettings.TurboMode,"held turbo stays on"));Raw("turbo-release");Raw("turbo-off",["ControlLeft","F7"]);Do("turbo-disabled",()=>Check(!w.ProbeSettings.TurboMode,"new edge disables"));Raw("turbo-off-release");
        Menu("Settings",11);Do("settings-screenshot",()=>RuntimeSmoke.Screenshot(w,Path.Combine(output,"settings.png")));Menu("Keyboard",14);Do("keyboard-screenshot",()=>RuntimeSmoke.Screenshot(w,Path.Combine(output,"keyboard.png")));Menu("Controller",14);Do("controller-screenshot",()=>RuntimeSmoke.Screenshot(w,Path.Combine(output,"controller.png")));
        Menu("Media");Do("media-browser-screenshot",()=>RuntimeSmoke.Screenshot(w,Path.Combine(output,"media.png")));Do("invalid-drop",()=>w.OnUserFileDrop([Path.Combine(output,"missing.sfc")]));Wait("invalid-drop-completed",()=>!w.MediaOperationPending);Do("invalid-drop-visible",()=>{Check(w.VisibleStatus.Contains("missing.sfc",StringComparison.OrdinalIgnoreCase),"drop error visible");RuntimeSmoke.Screenshot(w,Path.Combine(output,"drop-error.png"));});Menu("Reset");Do("reset-screenshot",()=>RuntimeSmoke.Screenshot(w,Path.Combine(output,"reset.png")));
        w.RenderFrame+=_=>{if(timer.Elapsed.TotalSeconds>90)throw new TimeoutException("M9g native at "+(steps.TryPeek(out var pending)?pending.Name:"end"));if(timer.Elapsed.TotalSeconds<next)return;if(steps.Count==0){w.Close();return;}var step=steps.Peek();if(!step.Run())return;steps.Dequeue();completed++;rows.Add(new{step.Name,WallSeconds=timer.Elapsed.TotalSeconds,Menu=w.CurrentMenu,Selection=w.ProbeSelection,Capturing=w.ProbeCapturing,Pad=w.ProbePadButtons,Keyboard=w.ProbeKeyboardButtons});File.WriteAllText(Path.Combine(output,"progress.json"),JsonSerializer.Serialize(rows));next=timer.Elapsed.TotalSeconds+.08;};
        w.Run();Check(steps.Count==0,"all native stages completed");BindingEditor.Probe(output);
        File.WriteAllText(Path.Combine(output,"result.json"),JsonSerializer.Serialize(new{Success=true,Completed=completed,Rows=rows,SyntheticRawSnapshots=true,PhysicalPad=false,OsFocusAutomation=false},new JsonSerializerOptions{WriteIndented=true}));
    }
}
